    // ── Progress fraction ──────────────────────────────────────────────────

    [Fact]
    public void ProgressFraction_UsesRelayStagesDenominator()
    {
        var denominator = (double)RelayStages.All.Count;
        var fullRow = new TaskRowViewModel(NewTask(RelayStages.All.Count));
        Assert.Equal(1.0, fullRow.ProgressFraction, precision: 6);

        var halfRow = new TaskRowViewModel(NewTask(RelayStages.All.Count / 2));
        Assert.Equal((RelayStages.All.Count / 2) / denominator, halfRow.ProgressFraction, precision: 6);
    }

    [Fact]
    public void ProgressFraction_UsesLiveCountWhenRunning()
    {
        var denominator = (double)RelayStages.All.Count;
        var row = new TaskRowViewModel(NewTask(0));
        Assert.Equal(0.0, row.ProgressFraction);

        row.MarkRunning();
        Assert.Equal(0.0, row.ProgressFraction);

        var changed = new List<string>();
        row.PropertyChanged += (_, e) => changed.Add(e.PropertyName ?? "");

        // Complete every stage via RecordStageCompleted (simulates stage_done events).
        for (var i = 1; i <= RelayStages.All.Count; i++)
        {
            row.RecordStageCompleted(i);
        }

        Assert.Equal(1.0, row.ProgressFraction, precision: 6);
        // ProgressFraction must have been raised for each completion.
        Assert.Equal(RelayStages.All.Count, changed.Count(p => p == "ProgressFraction"));
    }

    [Fact]
    public void ProgressFraction_FallsBackToRunMetricsWhenIdle()
    {
        var denominator = (double)RelayStages.All.Count;

        // Idle row with CompletedStageCount = 6 → fraction from RunMetrics.
        var row = new TaskRowViewModel(NewTask(6));
        Assert.Equal(6.0 / denominator, row.ProgressFraction, precision: 6);

        // Switch to running, simulate 3 live completions.
        row.MarkRunning();
        row.RecordStageCompleted(1);
        row.RecordStageCompleted(2);
        row.RecordStageCompleted(3);

        // Running: fraction from live count (3), not RunMetrics (6).
        Assert.Equal(3.0 / denominator, row.ProgressFraction, precision: 6);

        // Back to idle: reverts to RunMetrics fraction (6).
        row.MarkIdle();
        Assert.Equal(6.0 / denominator, row.ProgressFraction, precision: 6);
    }

    [Fact]
    public void UpdateTask_NotifiesProgressFraction()
    {
        var row = new TaskRowViewModel(NewTask(2));
        var changed = new List<string>();
        row.PropertyChanged += (_, e) => changed.Add(e.PropertyName ?? "");

        row.UpdateTask(NewTask(8));

        Assert.Contains("ProgressFraction", changed);
